template.inlineTemplate:
#!/bin/sh echo "========================================" echo " Zowe APIML Health Report" echo "========================================" echo " Gateway version : ${instance-GATEWAY_VERSION}" echo " Gateway status : ${instance-GATEWAY_STATUS}" echo " Discovery status : ${instance-DISCOVERY_STATUS}" echo " Services registered: ${instance-SERVICE_COUNT}" echo " Catalog status : ${instance-CATALOG_STATUS}" echo " API tiles published: ${instance-CATALOG_COUNT}" echo "----------------------------------------" echo " Summary: ${instance-HEALTH_SUMMARY}" echo "========================================"
RC=0 if [ "${instance-GATEWAY_STATUS}" != "200" ]; then echo "FAIL: API Gateway returned ${instance-GATEWAY_STATUS} (expected 200)" RC=1 fi if [ "${instance-DISCOVERY_STATUS}" != "200" ]; then echo "FAIL: Discovery Service returned ${instance-DISCOVERY_STATUS} (expected 200)" RC=1 fi if [ "${instance-CATALOG_STATUS}" != "200" ]; then echo "FAIL: API Catalog returned ${instance-CATALOG_STATUS} (expected 200)" RC=1 fi
if [ $RC -eq 0 ]; then echo "SUCCESS: All three APIML services are healthy" fi exit $RC
